import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { SEED_STRUCTURES } from '../src/structures.ts';

/**
 * Emits `structure-index.ts`: for each structure that has a written body, how
 * much of one, in three numbers.
 *
 * Why a generated file rather than reading the catalogue. `structures.ts` and
 * its depth files are ~600KiB and sit behind a dynamic `import()` on purpose
 * (see the header of apps/web/src/api/structureFallback.ts). But the topic
 * LIST is the first thing a reader sees on entering the connection explorer,
 * and until now its only label described island mappings — the one dimension
 * on which most of these topics are empty — while saying nothing about the
 * dimension on which most of them are now full. Marking the list needs three
 * integers per topic, not the prose, so the integers ship eagerly and the
 * prose stays deferred.
 *
 * `relations` is the DEGREE — relations authored on this structure plus those
 * pointing at it — because that is what the reader can actually click on when
 * they open it, not the outbound count alone.
 */
const outPath = fileURLToPath(new URL('../src/structure-index.ts', import.meta.url));
const check = process.argv.includes('--check');

const inbound = new Map();
for (const structure of SEED_STRUCTURES) {
  for (const relation of structure.depth?.relations ?? []) {
    inbound.set(relation.to, (inbound.get(relation.to) ?? 0) + 1);
  }
}

const entries = Object.fromEntries(
  SEED_STRUCTURES.filter((structure) => structure.depth).map((structure) => [
    structure.id,
    {
      substrates: structure.depth.canonicalSubstrates.length,
      fields: new Set(structure.depth.canonicalSubstrates.map((substrate) => substrate.field.zh)).size,
      relations: structure.depth.relations.length + (inbound.get(structure.id) ?? 0),
    },
  ]),
);

const source = `/**
 * GENERATED by scripts/generate-structure-index.mjs — do not edit by hand.
 *
 * How much written body each structure has, in three integers, small enough to
 * ship eagerly. Absence from this record means the structure has a statement
 * and nothing else — which is real content about the catalogue, not a loading
 * state, so a consumer may render the absence directly.
 *
 * The body itself (origin, minimal form, textbook substrates, relations,
 * what it gets mistaken for) lives in \`structures.ts\` and its depth files and
 * must stay behind a dynamic \`import()\`.
 */

export interface StructureReadingIndexEntry {
  /** Textbook instances written for this structure. */
  substrates: number;
  /** Distinct disciplines those instances come from. */
  fields: number;
  /** Relations a reader can follow from it: authored here plus pointing at it. */
  relations: number;
}

export const STRUCTURE_READING_INDEX: Record<string, StructureReadingIndexEntry> = ${JSON.stringify(entries, null, 2)};

export function structureReadingIndex(id: string): StructureReadingIndexEntry | undefined {
  return STRUCTURE_READING_INDEX[id];
}
`;

if (check) {
  const current = await readFile(outPath, 'utf8').catch(() => '');
  if (current !== source) {
    console.error('packages/data/src/structure-index.ts is stale. Run pnpm --filter @frontier-isles/data generate:structure-index.');
    process.exitCode = 1;
  }
} else {
  await writeFile(outPath, source);
  console.log(`Generated reading index for ${Object.keys(entries).length} of ${SEED_STRUCTURES.length} structures at packages/data/src/structure-index.ts.`);
}
